 function setMood(m){state.mood=m;document.querySelectorAll('.mood').forEach(b=>{let on=b.dataset.mood===m;b.classList.toggle('selected',on);b.setAttribute('aria-checked',on)})}
 document.querySelectorAll('.mood').forEach(b=>b.onclick=()=>setMood(b.dataset.mood));
 function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
 function start(){state.names=[$('#name1').value.trim()||'Player One',$('#name2').value.trim()||'Player Two'];state.deck=shuffle([...decks[state.mood]]);state.index=0;state.turn=Math.random()<.5?0:1;state.passed=0;state.seen=0;state.off={};intro.classList.remove('active');game.classList.add('active');$('#gameFooter').style.display='block';draw();window.scrollTo(0,0)}
-function draw(){if(state.index>=state.deck.length){end(true);return}let c=state.deck[state.index],card=$('#promptCard');card.style.animation='none';void card.offsetWidth;card.style.animation='flip .35s ease both';$('#cardTag').textContent=c[0];$('#promptText').textContent=c[1];$('#cardHint').textContent=c[2];$('#roundText').textContent='· '+String(state.index+1).padStart(2,'0');$('#turnName').textContent=state.names[state.turn];$('#playerOne').textContent=state.names[0];$('#playerTwo').textContent=state.names[1];$('#playerOne').classList.toggle('active',state.turn===0);$('#playerTwo').classList.toggle('active',state.turn===1);$('#deckCount').textContent=(state.deck.length-state.index-1)+' prompts left';$('#progress').innerHTML=state.deck.map((_,i)=>`<span class="${i<state.index?'done':''}"></span>`).join('');$('#nextBtn').textContent=state.index===state.deck.length-1?'Finish our evening ♡':'We did it · Next prompt';}
+function isBlocked(card){let text=(card[0]+' '+card[1]).toLowerCase();let terms={affection:['affection','cuddle','hug','kiss','touch','hand squeeze','sit a little closer','slow dance','close in','closer, maybe'],vulnerable:['what helps you feel','share a kind','what would help you feel','something you have always','what have you','honest check-in','something you admire','first real conversation'],eye:['eye contact']};return Object.entries(state.off).some(([kind,on])=>on&&(terms[kind]||[]).some(word=>text.includes(word)))}
+function draw(){while(state.index<state.deck.length&&isBlocked(state.deck[state.index]))state.index++;if(state.index>=state.deck.length){end(true);return}let c=state.deck[state.index],card=$('#promptCard');card.style.animation='none';void card.offsetWidth;card.style.animation='flip .35s ease both';$('#cardTag').textContent=c[0];$('#promptText').textContent=c[1];$('#cardHint').textContent=c[2];$('#roundText').textContent='· '+String(state.index+1).padStart(2,'0');$('#turnName').textContent=state.names[state.turn];$('#playerOne').textContent=state.names[0];$('#playerTwo').textContent=state.names[1];$('#playerOne').classList.toggle('active',state.turn===0);$('#playerTwo').classList.toggle('active',state.turn===1);$('#deckCount').textContent=(state.deck.length-state.index-1)+' prompts left';$('#progress').innerHTML=state.deck.map((_,i)=>`<span class="${i<state.index?'done':''}"></span>`).join('');$('#progress').children[state.index].classList.add('done');$('#nextBtn').textContent=state.index===state.deck.length-1?'Finish our evening ♡':'We did it · Next prompt';}
 function advance(passed){if(passed)state.passed++;else state.seen++;state.index++;state.turn=1-state.turn;draw()}
 function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('show');let b=$('#modalContent button');if(b)b.focus()}
 function closeModal(){$('#modalBackdrop').classList.remove('show')}
 function boundaries(){openModal(`<h2 id="modalTitle">Your comfort, your call.</h2><p>Use these to skip any kind of prompt you do not want tonight. Your settings stay on this device for this round only. A pass is always enough; toggles are optional.</p><div class="boundary-list"><label class="boundary">Skip affection prompts<input class="toggle" type="checkbox" data-off="affection" ${state.off.affection?'checked':''}></label><label class="boundary">Skip vulnerable questions<input class="toggle" type="checkbox" data-off="vulnerable" ${state.off.vulnerable?'checked':''}></label><label class="boundary">Skip eye-contact prompts<input class="toggle" type="checkbox" data-off="eye" ${state.off.eye?'checked':''}></label></div><p>Every player can pause or stop the game at any time. No explanation needed.</p><div class="modal-footer"><button class="save" id="saveBoundaries">Got it</button></div>`);document.querySelectorAll('[data-off]').forEach(x=>x.onchange=()=>state.off[x.dataset.off]=x.checked);$('#saveBoundaries').onclick=()=>{closeModal();skipBlocked()}}

