 function end(completed){let seen=state.seen,passed=state.passed;game.classList.remove('active');$('#gameFooter').style.display='none';intro.classList.add('active');openModal(`<div class="end-content"><div class="heart">♡</div><h2 id="modalTitle">${completed?'What a lovely evening.':'Thanks for sharing a moment.'}</h2><p>${completed?'Hope you found a new favorite little thing about each other.':'You can always come back to the conversation when it feels right.'}</p><div class="end-stats"><strong>${seen}</strong> shared ${seen===1?'prompt':'prompts'} · <strong>${passed}</strong> passed, no questions asked</div><div class="modal-footer" style="justify-content:center"><button class="save" id="restartBtn">Start another round</button><button id="closeEnd">Close</button></div></div>`);$('#restartBtn').onclick=()=>{closeModal();start()};$('#closeEnd').onclick=closeModal}
