 $('#playerOne').onclick=()=>{state.turn=0;draw()};$('#playerTwo').onclick=()=>{state.turn=1;draw()};
 $('#rulesBtn').onclick=()=>openModal(`<h2 id="modalTitle">How to play</h2><p>Pick a mood and take turns with the prompts. Read yours aloud, answer—or don't—and enjoy the conversation that follows. You can change whose turn it is anytime.</p><p><strong style="color:#f5a8b9">Pass</strong> skips a prompt without explanation. <strong style="color:#f5a8b9">Boundaries</strong> lets you hide some prompt types. Pause, change your mind, or end the game whenever you like. This game is for consenting adults (18+) and keeps everything on your device.</p><p>There are no points to win. The only goal is to have a good time together.</p><div class="modal-footer"><button class="save" id="rulesClose">Sounds good</button></div>`);document.addEventListener('click',e=>{if(e.target.id==='rulesClose')closeModal()});
